import{_ as e,h as t,i as n,n as r}from"./createLucideIcon-DB9Lcjli.js";import{t as i}from"./user-round-CSmSmO3K.js";import{r as a}from"./ui-Bf6a0UYW.js";import{Bt as o,Ht as s,Lt as c,Pt as l,Rt as u,Ut as d,at as f,bt as p,ct as m,dt as h,it as g,lt as _,mt as v,nt as y,rt as b,zt as x}from"./index-BHPSNmpt.js";var S=e(t(),1),C=[{title:`Library`,icon:d,intro:`Every recipe from the cookbooks and cooks on On350.`,steps:[`Search by recipe, ingredient, cookbook or author from the top of the Library.`,`Scroll down to The menu to browse by course: Mains, Soups, Desserts and more.`,`Tap a cookbook cover to see all its recipes, or an author to see their page.`,`Tap Follow on an author or cook to hear when they post something new. Then tap the small bell beside Following to choose how you hear about that person: bell and email, bell only, or nothing.`,`Profiles, next to Cookbooks, lists everyone you can follow. Tap See all to open the full page and show only cookbook authors, cooks or the people you follow.`,`For you (turn it on in Settings → For you) shows picks on the Library: Just released (new from people you follow), then topics built from what you save, rate, plan and cook, who you follow and what you search for. Tap See all for the full page, and New picks there for a fresh set.`]},{title:`What can I make?`,icon:v,intro:`Find recipes using what you already have at home.`,steps:[`Tap “What can I make with what I have?” under the Library search.`,`Type what’s in your fridge and pantry, or tap the suggestions.`,`Recipes you can make with the fewest extra things come first. “You have everything” means nothing is missing.`,`Leave “I have the basics” on if you have salt, oil, sugar, flour and spices. Your list is remembered for next time.`]},{title:`Recipes`,icon:x,intro:`Everything you need on one page.`,steps:[`Use − and + to change the servings; the amounts change with it. No servings written? Step whole batches instead.`,`Smart scaling: when you double a recipe, baking soda, salt and spices go up a little less, eggs stay whole, and it tells you which pan to use. A hollow dot marks a line that was adjusted. It works offline too.`,`Allergies: in Settings → Allergies, tick what you or your family are allergic to. Any recipe that contains it shows a red warning, also in cooking mode. It’s worked out from the ingredients, so always read the labels too.`,`Dairy recipe? Tap Parve next to Ingredients to see it with parve swaps (also in cooking mode).`,`Choose US, Metric or As written in Settings → Measurements.`,`Tap a step to mark it done while you cook.`,`Write your own notes at the bottom; only you can see them.`,`On a computer: drag any sideways row with the mouse to slide it, and the mouse wheel slides the course chips and tabs.`,`The screen stays on while a recipe is open.`,`Something wrong with a Library recipe? Tap the flag at the top to report it. Only the On350 team sees reports.`]},{title:`Cooking mode`,icon:x,intro:`Big, one-step-at-a-time screen for the kitchen.`,steps:[`Tap Cooking mode on a recipe.`,`Finishing a recipe notes that you made it. Only you see “You made this 2 weeks ago” on the recipe; tap I made this if you cooked without cooking mode.`,`On a phone, what each step needs shows right under it; tap Ingredients for the full list.`,`Swipe or tap Next and Back to move between steps, or tap a dot along the bottom to jump to that step.`,`Tap “Step 3 of 9” to see every step at once; finished ones get a tick.`,`On a tablet or computer, a faint “Up next” shows what’s coming.`,`Left halfway? Open cooking mode again within 12 hours and tap Pick up there.`,`The screen stays on the whole time you cook.`,`At the end, tap Done and rate it. The finish screen closes by itself after 3 seconds (touch it to keep it open).`]},{title:`Hands-free voice`,icon:p,intro:`Cook without touching the screen.`,steps:[`In cooking mode, tap the microphone.`,`Say “next”, “back”, “repeat” or “ingredients”.`,`Say “start timer” to start the time written in the step, and “time left” to hear how long is left.`,`It reads each step out loud for you.`]},{title:`Timers`,icon:y,intro:`Any time in a step is a button.`,steps:[`Tap a time like “50 minutes” in a step to start a timer.`,`It floats in the corner on every page, and keeps going if you close the app.`,`Pause it, add a minute, or tap × to stop it. It rings when it’s done.`,`Drag it anywhere on the screen. Push it off the left or right edge to tuck it away; tap the faded tab to bring it back.`,`Choose how it rings in Settings → Timer sound.`,`Turn on phone notifications (Settings → Notifications) and the alarm pops up on your phone even when On350 is closed or the phone is locked.`]},{title:`Scan or upload a recipe`,icon:h,intro:`Add your own family recipes.`,steps:[`Tap the orange Scan button in the menu.`,`Take a photo of a recipe card or cookbook page, upload a file, or choose “I’ll type it myself”.`,`On350 reads it and fills in the title, ingredients and steps. Check it and tap Save.`,`No photo of the dish? Tap “Make a picture” for an AI picture of how it might look.`]},{title:`My Cabinet`,icon:s,intro:`Your saved and uploaded recipes.`,steps:[`Tap the bookmark on any recipe to save it to your Cabinet.`,`Make folders (like “Shabbos” or “Kids’ favorites”) in your Cabinet. Open a folder and tap Add recipes to choose what goes in it.`,`On a computer or tablet, drag a recipe onto a folder in the side list.`,`Search your Cabinet from the top of the page.`]},{title:`Sharing`,icon:m,intro:`Send recipes and folders to family and friends.`,steps:[`Tap Share on a recipe to send a link.`,`Share a whole folder from its menu in your Cabinet.`,`People you share with can view, and save a copy if they have On350.`]},{title:`Event List`,icon:o,intro:`Plan the menu for Shabbos, Yom Tov or a simcha.`,steps:[`Make an event, like “Shabbos Parshas Noach” or “Sheva Brachos”.`,`Add recipes to it from any recipe page.`,`Swipe a recipe left and tick it when it’s made.`]},{title:`Shopping List`,icon:f,intro:`One list from all the recipes you’re making.`,steps:[`Tap Choose recipes and pick recipes (each shows a small photo), or a whole event like “Shabbos Parshas Noach”.`,`Every ingredient is added up into one list, sorted aisle by aisle: Produce, Meat & Poultry, Dairy & Eggs, Pantry.`,`Making a double batch? In Choose recipes, use − and + next to a chosen recipe (½× to 4×). Amounts use smart scaling, and a recipe you switched to Parve is listed the parve way.`,`Kinds of the same thing are added together, like “butter” and “unsalted butter”.`,`Need something that isn’t in a recipe? Type it in the box under the list (paper towels, milk). It goes under “Also” and is shared with the rest.`,`Tap an item to tick it off in the store. Tap the pencil to change the recipes.`,`Tap Share to send the list by WhatsApp, text message or email, or copy it. Once you’ve ticked some off, it sends only what’s left.`]},{title:`Ratings`,icon:b,intro:`Help others find the best recipes.`,steps:[`Rate a recipe after you make it, from the recipe page or the end of cooking mode.`,`You can’t rate your own recipes.`]},{title:`Membership`,icon:l,intro:`Unlock every recipe in the Library.`,steps:[`Settings → Membership shows your plan.`,`Start with a free trial, then monthly or yearly.`,`Change or cancel any time from the same place.`,`In the iPhone and Android apps, joining and managing your plan open on our website, on350.com, in your phone’s browser. Finish there and come back: the app opens everything by itself.`,`A membership is for one device at a time. Opening On350 on another phone, tablet or computer asks “Use it here instead?”, and the first device pauses until you switch back.`]},{title:`Settings`,icon:_,intro:`Make On350 yours.`,steps:[`Light or dark appearance, how measurements show, the timer sound, and For you (off until you turn it on).`,`Choose what reaches you under Notification settings (in the bell or in Settings): for new cookbooks, new recipes, messages (notes the people you follow send their followers) and news from On350, turn the bell and email on or off separately. Recipe emails start off; everything shows in the bell. Every email has a one-tap unsubscribe link. Turn on Phone notifications to get new recipes from people you follow, messages and timer alarms on this device. On iPhone, add On350 to your Home Screen first.`,`Change your name, email or password from Edit at the top of Settings, or delete your account. A new email needs confirming from both your old and new address.`,`Read the Terms of Use, Privacy Policy and Refund Policy under Help → Terms & privacy. When they change, On350 asks you to agree to the new version once.`]},{title:`Becoming a contributor`,icon:g,intro:`Share your recipes with everyone and earn from them.`,steps:[`The first time you publish, you read and sign the Contributor Agreement: type your name and tick the box. On350 keeps a copy.`,`Send 2 test recipes; once they’re approved you can publish straight to the Library.`,`When you’re approved, you choose a 4 to 6 digit contributor PIN.`,`You’re asked for the PIN each time you publish or open your Studio, so nobody else can post as you.`,`Forgot it? Tap “Forgot PIN?” when it asks, and we’ll email you a code to set a new one. To change it, tap Change PIN at the bottom of your Studio.`]},{title:`Contributor Studio`,icon:i,intro:`See how your recipes are doing.`,steps:[`Open it from Settings → Contributor Studio.`,`See views, ratings, followers and earnings.`,`Connect your bank to get paid, and message the On350 team.`,`Choose when a recipe goes live: on the recipe, tap Publish (next to Private, at the top), then Schedule. Pick Thursday 9 am, Friday 8 am, or any time. It goes live by itself and your followers hear about it then. Until then you can still edit it, change the time, or cancel (tap the Live pill).`,`Share one of your recipes with your followers: choose it, pick a starting point (New recipe, For Shabbos, Yom Tov, Weeknight, Behind the scenes) or write your own, see the preview, and tap Send to followers. A quick automatic check runs first; if it spots something (like a link or something not about cooking), On350 looks it over before it goes out.`,`Payouts are approved by On350 and sent each month once you’ve earned at least $10. Smaller amounts carry over to the next month.`],contributorsOnly:!0}],w=r();function T(){let[e,t]=(0,S.useState)(null);return(0,w.jsxs)(`div`,{className:`mx-auto max-w-2xl pb-10`,children:[(0,w.jsxs)(n,{to:`/`,className:`tap-area inline-flex items-center gap-1 text-[14px] font-medium text-ink-2`,children:[(0,w.jsx)(c,{size:17}),` Back`]}),(0,w.jsxs)(`header`,{className:`mt-3`,children:[(0,w.jsx)(`p`,{className:a,children:`Help`}),(0,w.jsx)(`h1`,{className:`mt-1 font-display text-[36px] leading-none font-bold tracking-[-0.035em]`,children:`Everything On350 does`}),(0,w.jsx)(`p`,{className:`mt-2 text-[15px] text-ink-2`,children:`Tap a feature to see how to use it.`})]}),(0,w.jsx)(`ul`,{className:`mt-6 divide-y divide-line overflow-hidden rounded-3xl bg-surface shadow-[0_1px_3px_rgba(0,0,0,0.08)] ring-[0.5px] ring-line`,children:C.map(({title:n,icon:r,intro:i,steps:a,contributorsOnly:o})=>{let s=e===n;return(0,w.jsxs)(`li`,{children:[(0,w.jsxs)(`button`,{type:`button`,"aria-expanded":s,onClick:()=>t(s?null:n),className:`flex w-full items-center gap-3.5 px-4 py-3.5 text-left transition active:bg-surface-2`,children:[(0,w.jsx)(`span`,{className:`grid size-9 shrink-0 place-items-center rounded-full bg-accent/12 text-accent`,children:(0,w.jsx)(r,{size:17})}),(0,w.jsxs)(`span`,{className:`min-w-0 flex-1`,children:[(0,w.jsxs)(`span`,{className:`block font-semibold`,children:[n,o&&(0,w.jsx)(`span`,{className:`ml-2 text-[12px] font-medium text-ink-2`,children:`Contributors`})]}),(0,w.jsx)(`span`,{className:`block text-[13px] text-ink-2`,children:i})]}),(0,w.jsx)(u,{size:18,className:`shrink-0 text-ink-2 transition ${s?`rotate-180`:``}`})]}),s&&(0,w.jsx)(`ol`,{className:`space-y-2 px-4 pb-4 pl-[66px]`,children:a.map((e,t)=>(0,w.jsxs)(`li`,{className:`flex gap-2.5 text-[15px] leading-snug`,children:[(0,w.jsx)(`span`,{className:`mt-px w-4 shrink-0 font-semibold text-accent tabular-nums`,children:t+1}),(0,w.jsx)(`span`,{children:e})]},t))})]},n)})})]})}export{T as HelpPage};